import React, { useState } from 'react';
import '../styles/Tests.css';

function Tests() {
  const [currentTest, setCurrentTest] = useState(0);
  const [userAnswers, setUserAnswers] = useState({});
  const [showResults, setShowResults] = useState(false);

  const tests = [
    {
      id: 'peaks',
      name: 'Peeks & Angles',
      questions: [
        {
          question: 'What is the main purpose of shoulder peeking?',
          options: [
            'To get kills',
            'To bait out shots and gather information',
            'To rush the enemy',
            'To throw grenades'
          ],
          correct: 1
        },
        {
          question: 'When should you avoid wide peeking?',
          options: [
            'During eco rounds',
            'When you have team support',
            'On T side',
            'When you have full utility'
          ],
          correct: 0
        },
        {
          question: 'What is the key element of counter-strafing?',
          options: [
            'Running and shooting',
            'Jumping around corners',
            'Stopping completely before shooting',
            'Crouching while moving'
          ],
          correct: 2
        }
      ]
    },
    {
      id: 'movement',
      name: 'Movement',
      questions: [
        {
          question: 'What is the running speed in CS2?',
          options: [
            '200 units/s',
            '250 units/s',
            '300 units/s',
            '350 units/s'
          ],
          correct: 1
        },
        {
          question: 'Which movement technique is silent?',
          options: [
            'Running',
            'Jumping',
            'Walking with Shift',
            'Bunny hopping'
          ],
          correct: 2
        },
        {
          question: 'What is the main purpose of counter-strafing?',
          options: [
            'To move faster',
            'To jump higher',
            'To stop instantly for accurate shooting',
            'To make less noise'
          ],
          correct: 2
        }
      ]
    },
    {
      id: 'sounds',
      name: 'Sound System',
      questions: [
        {
          question: 'What is the approximate range of running sounds?',
          options: [
            '400 units',
            '600 units',
            '800 units',
            '1000 units'
          ],
          correct: 2
        },
        {
          question: 'Which action produces the least sound?',
          options: [
            'Walking',
            'Crouch-walking',
            'Slow-walking (Shift)',
            'Both B and C are silent'
          ],
          correct: 3
        },
        {
          question: 'How are sounds affected through walls?',
          options: [
            'They are completely blocked',
            'They are reduced by 30-70%',
            'They remain the same',
            'They become louder'
          ],
          correct: 1
        }
      ]
    },
    {
      id: 'utility',
      name: 'Utility Usage',
      questions: [
        {
          question: 'Which grenade is most effective for site executes?',
          options: [
            'HE Grenade',
            'Flashbang',
            'Smoke Grenade',
            'Molotov'
          ],
          correct: 2
        },
        {
          question: 'What is a "pop flash"?',
          options: [
            'A flash that makes a loud sound',
            'A flash that detonates instantly with minimal warning',
            'A flash thrown high in the air',
            'A flash that bounces multiple times'
          ],
          correct: 1
        },
        {
          question: 'When should you save utility?',
          options: [
            'Never, use it immediately',
            'Only during eco rounds',
            'For post-plant situations',
            'When rushing sites'
          ],
          correct: 2
        }
      ]
    }
  ];

  const handleAnswer = (questionIndex, answerIndex) => {
    setUserAnswers({
      ...userAnswers,
      [`${currentTest}_${questionIndex}`]: answerIndex
    });
  };

  const calculateScore = () => {
    let correct = 0;
    let total = tests[currentTest].questions.length;
    
    tests[currentTest].questions.forEach((q, i) => {
      if (userAnswers[`${currentTest}_${i}`] === q.correct) {
        correct++;
      }
    });

    return { correct, total };
  };

  return (
    <div className="tests-page">
      <h1>CS2 Knowledge Tests</h1>
      
      <div className="test-navigation">
        {tests.map((test, index) => (
          <button
            key={test.id}
            className={currentTest === index ? 'active' : ''}
            onClick={() => {
              setCurrentTest(index);
              setShowResults(false);
              setUserAnswers({});
            }}
          >
            {test.name}
          </button>
        ))}
      </div>

      <div className="test-content">
        <h2>{tests[currentTest].name} Test</h2>
        
        {!showResults ? (
          <>
            {tests[currentTest].questions.map((q, questionIndex) => (
              <div key={questionIndex} className="question-card">
                <h3>Question {questionIndex + 1}</h3>
                <p>{q.question}</p>
                <div className="options">
                  {q.options.map((option, optionIndex) => (
                    <button
                      key={optionIndex}
                      className={
                        userAnswers[`${currentTest}_${questionIndex}`] === optionIndex
                          ? 'selected'
                          : ''
                      }
                      onClick={() => handleAnswer(questionIndex, optionIndex)}
                    >
                      {option}
                    </button>
                  ))}
                </div>
              </div>
            ))}
            
            <button 
              className="submit-button"
              onClick={() => setShowResults(true)}
            >
              Submit Test
            </button>
          </>
        ) : (
          <div className="results-card">
            <h3>Test Results</h3>
            {(() => {
              const { correct, total } = calculateScore();
              return (
                <>
                  <p>You got {correct} out of {total} questions correct!</p>
                  <p>Score: {Math.round((correct / total) * 100)}%</p>
                  {tests[currentTest].questions.map((q, i) => (
                    <div key={i} className="question-review">
                      <p>Question {i + 1}: {q.question}</p>
                      <p className={
                        userAnswers[`${currentTest}_${i}`] === q.correct
                          ? 'correct'
                          : 'incorrect'
                      }>
                        Your answer: {q.options[userAnswers[`${currentTest}_${i}`]]}
                      </p>
                      {userAnswers[`${currentTest}_${i}`] !== q.correct && (
                        <p className="correct-answer">
                          Correct answer: {q.options[q.correct]}
                        </p>
                      )}
                    </div>
                  ))}
                  <button
                    className="retry-button"
                    onClick={() => {
                      setShowResults(false);
                      setUserAnswers({});
                    }}
                  >
                    Try Again
                  </button>
                </>
              );
            })()}
          </div>
        )}
      </div>
    </div>
  );
}

export default Tests;
